window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-124"]=[{"id":"set2-WAMtwFoc","fingerprint":"8684fa0d5124126f","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este definiția corectă a incluziei dentare?","options":[{"id":"A","text":"Absența congenitală a unuia sau mai multor dinți din arcada dentară."},{"id":"B","text":"Rămânerea unui dinte complet format în interiorul osului maxilar sau submucos, mult peste vârsta sa normală de erupție."},{"id":"C","text":"Erupția parțială a unui dinte, unde o parte a coroanei rămâne acoperită de țesut moale sau os."},{"id":"D","text":"Migrarea unui dinte într-o poziție anormală pe arcadă, după erupția sa completă."},{"id":"E","text":"Formarea incompletă a unui dinte, care împiedică erupția acestuia la momentul potrivit."}],"correct":["B"],"pages":[468],"source":"set-2"},{"id":"set2-7lFCqSko","fingerprint":"08f6f9b13bfa701a","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații privind clasificarea incluziei dentare sunt corecte?","options":[{"id":"A","text":"În clasificarea românească, este considerată o anomalie dentară de clasa I."},{"id":"B","text":"Clasificarea americană o consideră o dizarmonie a sistemului dentar."},{"id":"C","text":"În clasificarea românească, este o anomalie dentară izolată de erupție."},{"id":"D","text":"Școala franceză o include în grupa dizarmoniilor sistemului dentar."},{"id":"E","text":"Clasificarea școlii germane o plasează în clasa I a anomaliilor."}],"correct":["C","D"],"pages":[468],"source":"set-2"},{"id":"set2-68W000SY","fingerprint":"1876fdb93d5d3d73","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Cum se ierarhizează frecvența incluziei dentare în funcție de tipul de dinți?","options":[{"id":"A","text":"Incluzia dinților temporari este mai frecventă decât cea a dinților supranumerari."},{"id":"B","text":"Cel mai frecvent interesează dinții supranumerari, urmați de cei permanenți și apoi de cei temporari."},{"id":"C","text":"Este la fel de frecventă la dinții permanenți și la cei supranumerari."},{"id":"D","text":"Afectează în principal dinții temporari, în special molarii inferiori."},{"id":"E","text":"Afectează cel mai des dinții permanenți, urmați de dinții supranumerari, iar cel mai rar dinții temporari."}],"correct":["E"],"pages":[468],"source":"set-2"},{"id":"set2-xcJB4739","fingerprint":"f531a55c0e84e3b2","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este ordinea descrescătoare a frecvenței incluziei în dentiția permanentă?","options":[{"id":"A","text":"Caninul superior, molarul de minte, premolarul 2 inferior, incisivul central superior."},{"id":"B","text":"Molarul de minte, caninul, premolarul 2, incisivul central superior."},{"id":"C","text":"Caninul, incisivul central superior, molarul de minte, premolarul 2."},{"id":"D","text":"Incisivul central superior, caninul, premolarul 2, molarul de minte."},{"id":"E","text":"Molarul de minte, premolarul 2 inferior, caninul superior, incisivul central superior."}],"correct":["B"],"pages":[468],"source":"set-2"},{"id":"set2-VQUZ1T0X","fingerprint":"7107da22d3d024fa","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este ordinea crescătoare a frecvenței incluziei dentare în dentiția permanentă?","options":[{"id":"A","text":"Caninul, molarul de minte, premolarul 2, incisivul central superior."},{"id":"B","text":"Molarul de minte, premolarul 2, caninul, incisivul central superior."},{"id":"C","text":"Incisivul central superior, premolarul 2 inferior, caninul superior, molarul de minte."},{"id":"D","text":"Molarul de minte, caninul, premolarul 2, incisivul central superior."},{"id":"E","text":"Caninul, incisivul central superior, premolarul 2, molarul de minte."}],"correct":["C"],"pages":[469],"source":"set-2"},{"id":"set2-lTj9rNoc","fingerprint":"4c1279a87bfe905c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații referitoare la epidemiologia incluziei dentare sunt adevărate?","options":[{"id":"A","text":"Incluzia se întâlnește cel mai frecvent la dinții permanenți."},{"id":"B","text":"În dentiția permanentă, premolarul 2 superior este mai frecvent inclus decât cel inferior."},{"id":"C","text":"Incluzia dinților temporari este foarte rară, afectând mai ales molarii inferiori."},{"id":"D","text":"Anomalia este mult mai prezentă la genul feminin decât la cel masculin."},{"id":"E","text":"Incluzia este la fel de frecventă la dinții permanenți și la cei supranumerari."}],"correct":["A","C","D"],"pages":[469],"source":"set-2"},{"id":"set2-PCNgMOzh","fingerprint":"9ad76eae07d4d67e","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce caracteristici sunt specifice incluziei de canin?","options":[{"id":"A","text":"Incidența la arcada superioară este mai mare decât la cea inferioară."},{"id":"B","text":"Din perspectivă ortodontică, reprezintă aproximativ 20% din totalul incluziilor."},{"id":"C","text":"Majoritatea cazurilor de incluzie de canin sunt unilaterale."},{"id":"D","text":"Incluzia bilaterală este mai frecventă decât cea unilaterală."},{"id":"E","text":"Localizarea palatinală este de două ori mai frecventă decât cea vestibulară."}],"correct":["A","C","E"],"pages":[469],"source":"set-2"},{"id":"set2-Qa55KQi3","fingerprint":"39c03ab1e99767df","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce este transmigrația dentară?","options":[{"id":"A","text":"O anomalie care afectează exclusiv incisivii centrali superiori, determinându-i să treacă de linia mediană."},{"id":"B","text":"O anomalie în care un canin neerupt, în special cel inferior, migrează și traversează linia mediană."},{"id":"C","text":"O anomalie în care un canin erupt migrează vestibular, traversând linia mediană."},{"id":"D","text":"Migrarea mezială a molarilor de minte dincolo de linia mediană."},{"id":"E","text":"Procesul normal de erupție al caninului superior, care are un traiect sinuos."}],"correct":["B"],"pages":[469],"source":"set-2"},{"id":"set2-_LrPQwV5","fingerprint":"0d5bbcf993ea5599","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele reprezintă motive pentru frecvența crescută a incluziei de canin?","options":[{"id":"A","text":"Are cea mai simplă cronologie de erupție, cu excepția molarului de minte."},{"id":"B","text":"Urmează cel mai sinuos traiect de la formare până la atingerea planului de ocluzie."},{"id":"C","text":"Are cel mai profund loc de formare."},{"id":"D","text":"Prezintă cea mai lungă perioadă de dezvoltare."},{"id":"E","text":"Caninul superior erupe în jurul vârstei de 11-13 ani."}],"correct":["B","C","D","E"],"pages":[469],"source":"set-2"},{"id":"set2-i50XRrp9","fingerprint":"d1d45ae2409d5075","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Cum sunt asociate cauzele generale și cele locale cu tipurile de incluzii dentare?","options":[{"id":"A","text":"Numai cauzele locale pot determina tulburări de erupție, indiferent de numărul de dinți afectați."},{"id":"B","text":"Atât cauzele locale, cât și cele generale sunt asociate exclusiv cu incluziile multiple."},{"id":"C","text":"Cauzele locale sunt implicate mai frecvent în incluziile multiple, iar cele generale în incluziile unice."},{"id":"D","text":"Nu există nicio corelație între tipul cauzei (locală/generală) și numărul de dinți incluși."},{"id":"E","text":"Cauzele generale sunt implicate mai frecvent în incluziile multiple, iar cele locale în incluziile unice."}],"correct":["E"],"pages":[469],"source":"set-2"},{"id":"set2-58kQkQa6","fingerprint":"fa19be154a7e7ebe","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce condiție definește macrodonția relativă?","options":[{"id":"A","text":"O dezvoltare insuficientă a maxilarelor în plan transversal."},{"id":"B","text":"O situație în care suma incisivă depășește 35 mm."},{"id":"C","text":"O situație în care lățimea mezio-distală a fiecărui incisiv central este de 1 cm sau mai mult."},{"id":"D","text":"O situație în care deși dinții sunt de dimensiuni normale, dinții sunt mari în raport cu diametrul bizigomatic osos al subiectului."},{"id":"E","text":"O situație în care suma incisivă este exact 1/3 din diametrul bizigomatic osos."}],"correct":["D"],"pages":[469],"source":"set-2"},{"id":"set2-DccrgkiC","fingerprint":"3749f434920656e9","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele criterii pot fi utilizate pentru a diagnostica macrodonția absolută?","options":[{"id":"A","text":"Suma incisivă este mai mare decât 1/3 din diametrul bizigomatic osos."},{"id":"B","text":"Suma incisivă este mai mare de 35 mm."},{"id":"C","text":"Incisivii centrali au o lățime mezio-distală de 1 cm fiecare sau peste această valoare."},{"id":"D","text":"Suma incisivă este mai mică decât 1/3 din diametrul bizigomatic osos."},{"id":"E","text":"Suma incisivă este în limite normale, sub valoarea de 35 mm."}],"correct":["A","B","C"],"pages":[469],"source":"set-2"},{"id":"set2-g6kF3hTC","fingerprint":"c912982e2cd97c14","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce dinți sunt cel mai frecvent afectați de incluzie ca o consecință a dezvoltării insuficiente a maxilarelor în plan transversal?","options":[{"id":"A","text":"Toți dinții de pe arcada superioară, în mod egal."},{"id":"B","text":"Primul premolar superior și primul molar inferior."},{"id":"C","text":"Caninul superior, al doilea premolar inferior și molarii de minte."},{"id":"D","text":"Incisivii centrali superiori și laterali."},{"id":"E","text":"Caninul inferior și al doilea premolar superior."}],"correct":["C"],"pages":[469],"source":"set-2"},{"id":"set2-p9Tc57wG","fingerprint":"fa4a4edf79145c34","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații descriu corect meziopozițiile generalizate (MPG) și consecințele acestora?","options":[{"id":"A","text":"Pot explica atât incluziile unilaterale, cât și pe cele bilaterale."},{"id":"B","text":"Se caracterizează prin migrarea distală a dinților din zonele laterale."},{"id":"C","text":"Facilitează erupția molarului de 6 ani mult mai mezial decât locul său real pe arcadă."},{"id":"D","text":"Sunt o consecință a distrucțiilor coronare masive sau a pierderilor precoce ale dinților temporari din zona de sprijin."},{"id":"E","text":"Oferă substrat explicativ real pentru incluziile tuturor dinților, cu precădere pentru molarii de minte."}],"correct":["A","C","D"],"pages":[470],"source":"set-2"},{"id":"set2-ouLHr9Lr","fingerprint":"3c69e2fb1d2c6837","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"În ceea ce privește etiopatogenia incluziei de canin permanent, care este relația dintre deficitul de spațiu și localizarea incluziei?","options":[{"id":"A","text":"Traiectul evolutiv normal al caninului este orientat spre oral, ceea ce face ca deficitul de spațiu să determine o incluzie vestibulară."},{"id":"B","text":"Incluzia cu localizare orală este frecvent asociată cu existența unui spațiu suficient pentru erupție pe arcadă."},{"id":"C","text":"Deficitul de spațiu este considerat un factor cauzal major atât pentru incluzia vestibulară, cât și pentru cea orală."},{"id":"D","text":"Etiologia incluziei de canin cu localizare palatinală este orientată exclusiv către deficitul de spațiu."},{"id":"E","text":"O cauză genetică este sugerată pentru incluzia vestibulară, datorită asocierii cu anodonția."}],"correct":["B"],"pages":[470],"source":"set-2"},{"id":"set2-UR47gq4D","fingerprint":"ea0e6a07259206e7","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Cum contribuie procesul de reducere filogenetică la apariția incluziilor dentare?","options":[{"id":"A","text":"Procesul de reducție se desfășoară cu aceeași viteză pentru toate componentele aparatului dento-maxilar."},{"id":"B","text":"Prin reducerea mai rapidă a numărului și volumului dentar comparativ cu oasele maxilare."},{"id":"C","text":"Acest proces creează un excedent de spațiu pentru alinierea dentară, prevenind incluziile."},{"id":"D","text":"Procesul afectează cu precădere dinții care erup primii pe arcadă."},{"id":"E","text":"Ritmul de reducere al maxilarelor este mai accelerat decât cel de reducere al elementelor dentare."}],"correct":["E"],"pages":[470],"source":"set-2"},{"id":"set2-YRchKwx2","fingerprint":"f69d10e860ec3156","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele elemente sunt considerate obstacole directe în calea erupției unui dinte?","options":[{"id":"A","text":"Persistența caninilor temporari peste termenul normal de permutare."},{"id":"B","text":"Reducerea filogenetică a elementelor componente ale aparatului dento-maxilar."},{"id":"C","text":"Dezvoltarea insuficientă a oaselor maxilare."},{"id":"D","text":"Existența unor formațiuni tumorale precum odontoamele."},{"id":"E","text":"Prezența dinților supranumerari pe traseul de erupție."}],"correct":["A","D","E"],"pages":[470],"source":"set-2"},{"id":"set2-aGCUbiBm","fingerprint":"4f98461195d2fabe","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Comparând diferiți factori etiologici locali ai incluziilor dentare, care afirmație este corectă?","options":[{"id":"A","text":"Meziopozițiile generalizate (MPG) explică mai ales incluziile bilaterale, în timp ce macrodonția explică mai ales incluziile unilaterale."},{"id":"B","text":"Macrodonția și dezvoltarea insuficientă a maxilarelor pot oferi un suport explicativ pentru toate tipurile de incluzii, în special pentru dinții care erup ultimii."},{"id":"C","text":"Meziopozițiile generalizate (MPG) oferă substrat explicativ real exclusiv pentru incluziile de canini la arcada inferioară."},{"id":"D","text":"Dinții supranumerari au o afinitate pentru regiunea posterioară, determinând frecvent incluzii de molari."},{"id":"E","text":"Atât macrodonția, cât și MPG susțin explicativ doar incluziile bilaterale."}],"correct":["B"],"pages":[470],"source":"set-2"},{"id":"set2-mGf2t1tj","fingerprint":"97b09f53f8fb40a1","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele condiții pot duce la osteoscleroza procesului alveolar, un factor local în etiologia incluziei dentare?","options":[{"id":"A","text":"Procesele inflamatorii cronice de la dinții temporari"},{"id":"B","text":"Plastia despicăturilor labio-maxilo-palatine"},{"id":"C","text":"Osteita deformantă"},{"id":"D","text":"Hiperplaziile gingivale"},{"id":"E","text":"Traumatismele maxilare"}],"correct":["A","B","C","E"],"pages":[471],"source":"set-2"},{"id":"set2-uMqZEHOJ","fingerprint":"7f2660dfc971a04b","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele caracteristici morfologice sau de poziționare ale unui dinte sunt considerate factori favorizanți pentru incluzia sa?","options":[{"id":"A","text":"Un potențial eruptiv crescut"},{"id":"B","text":"O curbură radiculară accentuată"},{"id":"C","text":"O coroană foarte globuloasă"},{"id":"D","text":"Poziția intraosoasă profundă a mugurelui dentar"},{"id":"E","text":"O angulație corono-radiculară redusă"}],"correct":["B","C","D"],"pages":[471],"source":"set-2"},{"id":"set2-wwMqym3P","fingerprint":"a6796dec7ce34024","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afecțiuni sunt clasificate ca factori generali în etiologia incluziei dentare?","options":[{"id":"A","text":"Nanismul hipofizar"},{"id":"B","text":"Hemiatrofia facială (sindromul Romberg)"},{"id":"C","text":"Malpozițiile dinților vecini"},{"id":"D","text":"Rahitismul"},{"id":"E","text":"Disostoza cleidocraniană"}],"correct":["A","D","E"],"pages":[471],"source":"set-2"},{"id":"set2-2KsN_X20","fingerprint":"fae2f7a54afc9ad3","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care dintre următoarele este o cauză a formării unei fibromucoase dense și dure, reprezentând un factor local în incluzia dentară?","options":[{"id":"A","text":"Nanismul hipofizar"},{"id":"B","text":"Extracțiile precoce"},{"id":"C","text":"Osteita deformantă"},{"id":"D","text":"Poziția intraosoasă profundă a mugurelui dentar"},{"id":"E","text":"Rahitismul"}],"correct":["B"],"pages":[471],"source":"set-2"},{"id":"set2-cJJkTInG","fingerprint":"56a57c3f947a242a","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Factorul ereditar în incluzia de canin este frecvent asociat cu alte anomalii dentare determinate genetic. Care dintre următoarele anomalii este menționată în acest context?","options":[{"id":"A","text":"Disostoza cleidocraniană"},{"id":"B","text":"Erupția spontană a caninului la vârste înaintate"},{"id":"C","text":"Osteoscleroza procesului alveolar"},{"id":"D","text":"O angulație corono-radiculară accentuată a caninului"},{"id":"E","text":"Anodonția incisivului lateral"}],"correct":["E"],"pages":[471],"source":"set-2"},{"id":"set2-Ihbjl077","fingerprint":"53c78f0e5f260dea","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce tip de modificare a poziției anormale intraosoase a unui dinte este menționat ca factor favorizant al incluziei dentare?","options":[{"id":"A","text":"Modificare în sens vertical, prin formarea mugurelui într-o poziție foarte înaltă"},{"id":"B","text":"Modificare în sens sagital, cu mezioînclinații ce pot ajunge la poziții orizontale"},{"id":"C","text":"Modificare în sens transversal, cu dintele așezat de-a curmezișul arcadei"},{"id":"D","text":"Modificare de rotație în jurul axului lung al dintelui"},{"id":"E","text":"Modificare combinată, atât în sens sagital, cât și transversal"}],"correct":["B","C","E"],"pages":[471],"source":"set-2"},{"id":"set2-CzfNOmFD","fingerprint":"01c26ad059843606","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce disfuncție specifică este menționată în contextul disostozei cleidocraniene ca posibilă explicație pentru fenomenul incluziei dentare?","options":[{"id":"A","text":"O atrofie progresivă a hemifeței"},{"id":"B","text":"O disfuncție a osteoclastelor"},{"id":"C","text":"O deficiență de vitamina D"},{"id":"D","text":"O hipersecreție de hormon de creștere"},{"id":"E","text":"O tulburare a osteoblastelor"}],"correct":["B"],"pages":[471],"source":"set-2"},{"id":"set2-YhBVghB-","fingerprint":"aff4ff24fdee5c78","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt afirmațiile corecte referitoare la clasificarea clinico-evolutivă a incluziei dentare?","options":[{"id":"A","text":"În incluzia parțială, coroana dintelui este complet înconjurată de os."},{"id":"B","text":"Incluzia completă presupune că o parte a coroanei dintelui este vizibilă în cavitatea orală."},{"id":"C","text":"Incluzia totală se caracterizează prin faptul că dintele inclus se află în întregime intraosos sau submucos."},{"id":"D","text":"În incluzia incompletă, coroana este separată de cavitatea orală prin sacul pericoronar și fibromucoasă."},{"id":"E","text":"Incluzia parțială și cea totală sunt clasificate în funcție de distanța în milimetri până la planul de ocluzie."}],"correct":["C","D"],"pages":[472],"source":"set-2"},{"id":"set2-eO8z55I8","fingerprint":"7acd937819d85ee2","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Cum este clasificată o incluzie dentară a cărei distanță până la planul de ocluzie, măsurată pe ortopantomogramă, este de 17 mm?","options":[{"id":"A","text":"Incluzie dentară joasă"},{"id":"B","text":"Incluzie de canin gradul 3"},{"id":"C","text":"Incluzie dentară ușoară"},{"id":"D","text":"Incluzie dentară medie"},{"id":"E","text":"Incluzie dentară severă"}],"correct":["E"],"pages":[472],"source":"set-2"},{"id":"set2-Lps5gJGx","fingerprint":"625e98df022f616f","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"În cazul unei incluzii de canin superior, ce grad de severitate indică un unghi de 20° format de axul caninului cu linia mediană?","options":[{"id":"A","text":"Incluzie de canin gradul 2"},{"id":"B","text":"Incluzie de canin gradul 1"},{"id":"C","text":"Incluzie de canin gradul 3"},{"id":"D","text":"Incluzie de canin gradul 4"},{"id":"E","text":"Incluzie dentară medie"}],"correct":["A"],"pages":[472],"source":"set-2"},{"id":"set2-YW3eIYlH","fingerprint":"e830d1e25ae36bf0","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce grad de incluzie de canin superior corespunde situației în care apexul caninului este situat deasupra regiunii primului premolar?","options":[{"id":"A","text":"Incluzie de canin gradul 1"},{"id":"B","text":"Incluzie de canin severă"},{"id":"C","text":"Incluzie de canin gradul 2"},{"id":"D","text":"Incluzie de canin gradul 3"},{"id":"E","text":"Incluzie de canin gradul 4"}],"correct":["C"],"pages":[472],"source":"set-2"},{"id":"set2-A_hp-ktt","fingerprint":"3088e758a831d053","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este clasificarea corectă a unei incluzii de canin superior, dacă coroana acestuia se află deasupra nivelului joncțiunii smalț-cement, dar la mai puțin de jumătate din înălțimea rădăcinii incisivului lateral?","options":[{"id":"A","text":"Incluzie de canin gradul 3"},{"id":"B","text":"Incluzie de canin gradul 1"},{"id":"C","text":"Incluzie de canin gradul 4"},{"id":"D","text":"Incluzie de canin parțială"},{"id":"E","text":"Incluzie de canin gradul 2"}],"correct":["E"],"pages":[472],"source":"set-2"},{"id":"set2-bpGzNGoV","fingerprint":"1c21e64e91f8fe94","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Selectați afirmațiile corecte referitoare la clasificarea incluziei de canin superior în funcție de gradul de suprapunere peste rădăcina incisivului adiacent:","options":[{"id":"A","text":"Gradul 4 se caracterizează prin suprapunerea completă a caninului inclus peste lățimea rădăcinii incisivului lateral."},{"id":"B","text":"Gradul 1 este caracterizat prin absența suprapunerii caninului inclus peste rădăcina incisivului lateral."},{"id":"C","text":"Gradul 1 implică o suprapunere peste mai puțin de jumătate din lățimea rădăcinii incisivului lateral."},{"id":"D","text":"Gradul 3 este definit de o suprapunere ce acoperă în totalitate lățimea rădăcinii incisivului lateral."},{"id":"E","text":"Gradul 2 semnifică faptul că dintele inclus nu se suprapune deloc peste rădăcina incisivului lateral."}],"correct":["A","B"],"pages":[472],"source":"set-2"},{"id":"set2-zYRSHx7m","fingerprint":"cc28d06afdac1aba","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Conform clasificării incluziilor dentare în funcție de direcția axului dintelui, ce definește o incluzie dentară vestibulo-orală?","options":[{"id":"A","text":"Coroana dintelui inclus este situată între rădăcinile dinților erupți."},{"id":"B","text":"Axul dintelui inclus este vertical."},{"id":"C","text":"Coroana dintelui inclus este orientată spre mezial."},{"id":"D","text":"Coroana dintelui are o orientare inversă sensului de erupție."},{"id":"E","text":"Dintele inclus este orientat cu coroana spre vestibular și cu rădăcina spre oral."}],"correct":["E"],"pages":[473],"source":"set-2"},{"id":"set2-QE07JivP","fingerprint":"8611c29a2e0f84ed","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele tipuri de incluzii dentare sunt diferențiate în raport cu aspectul morfologic al dinților incluși?","options":[{"id":"A","text":"Incluzie dentară cu anchiloză dentară."},{"id":"B","text":"Incluzie dentară cu dinți normal constituiți."},{"id":"C","text":"Incluzie dentară submucoasă."},{"id":"D","text":"Incluzie dentară ectopică."},{"id":"E","text":"Incluzie dentară cu angulație corono-radiculară."}],"correct":["A","B","E"],"pages":[473],"source":"set-2"},{"id":"set2-ry0IL6gp","fingerprint":"94e31675951b9be4","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce termen definește situația în care un dinte se formează la distanță de locul său normal, de exemplu în condilul mandibular sau fosele nazale?","options":[{"id":"A","text":"Heterotopie dentară"},{"id":"B","text":"Incluzie dentară ectopică"},{"id":"C","text":"Incluzie în retroversie"},{"id":"D","text":"Incluzie dentară osoasă"},{"id":"E","text":"Incluzie dentară normală"}],"correct":["A"],"pages":[473],"source":"set-2"},{"id":"set2-wtg2SwGB","fingerprint":"9a57fa59e0e4d97f","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce tip de incluzie dentară necesită o intervenție chirurgicală care interesează exclusiv fibromucoasa?","options":[{"id":"A","text":"Incluzie dentară osoasă"},{"id":"B","text":"Incluzie dentară submucoasă"},{"id":"C","text":"Incluzie dentară multiplă"},{"id":"D","text":"Incluzie dentară ectopică"},{"id":"E","text":"Incluzie dentară orală"}],"correct":["B"],"pages":[473],"source":"set-2"},{"id":"set2-YjO859N8","fingerprint":"ce936bbd74ee93a3","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații referitoare la diagnosticul incluziei dentare sunt corecte?","options":[{"id":"A","text":"Persistența pe arcadă a predecesorilor temporari poate duce la descoperirea tardivă a incluziei dinților succesionali."},{"id":"B","text":"Simptomatologia incluziei dentare este specifică și concludentă din punct de vedere subiectiv."},{"id":"C","text":"Lipsa de pe arcadă a unui dinte permanent, deși termenul de erupție a fost depășit, poate sugera prezența unei incluzii."},{"id":"D","text":"Diagnosticul de certitudine se stabilește în urma investigației radiologice."},{"id":"E","text":"Incluziile înalte, unde dintele este plasat foarte profund, sunt ușor de decelat la palpare."}],"correct":["A","C","D"],"pages":[473],"source":"set-2"},{"id":"set2-x5WMYgVg","fingerprint":"4e65bd6d8d5487ba","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"În funcție de ce criteriu este definită o incluzie dentară ca fiind unică sau multiplă?","options":[{"id":"A","text":"Tipul intervenției chirurgicale"},{"id":"B","text":"Numărul dinților incluși"},{"id":"C","text":"Locul în care se dezvoltă"},{"id":"D","text":"Aspectul morfologic"},{"id":"E","text":"Tipul dentiției"}],"correct":["B"],"pages":[473],"source":"set-2"},{"id":"set2-ooBg9L-I","fingerprint":"d26b8f14217b3e75","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele semne clinice intraorale pot sugera prezența unui dinte inclus?","options":[{"id":"A","text":"Lipsa de pe arcadă a dintelui permanent, deși termenul său de erupție este demult depășit."},{"id":"B","text":"Procese inflamatorii ale mucoasei, exclusiv pericoronarite."},{"id":"C","text":"Treme sau diasteme la nivelul dinților vecini."},{"id":"D","text":"Mobilitatea dinților vecini cauzată de resorbția radiculară."},{"id":"E","text":"Prezența unei deformări vestibulare sau orale, de consistență moale și depresibilă."}],"correct":["A","C","D"],"pages":[474],"source":"set-2"},{"id":"set2-DuR5xaaa","fingerprint":"852f2a695a13ffb7","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"În contextul incluziei caninului superior, care este semnul clinic patognomonic întâlnit în aproximativ 50% din cazuri?","options":[{"id":"A","text":"O disto-înclinație accentuată a incisivului lateral, cu coroana spre distal și apexul rădăcinii spre mezial."},{"id":"B","text":"Rotația mezio-vestibulară a coroanei incisivului lateral superior."},{"id":"C","text":"Resorbția radiculară severă la nivelul incisivului central."},{"id":"D","text":"Persistența pe arcadă a caninului temporar cu mobilitate crescută."},{"id":"E","text":"Prezența unei fistule cronice în dreptul incisivului lateral, fără răspuns terapeutic."}],"correct":["A"],"pages":[474],"source":"set-2"},{"id":"set2-SoWEoinn","fingerprint":"589708efbad80f21","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este cea mai frecventă complicație a incluziei caninului superior, având o incidență de 48%?","options":[{"id":"A","text":"Durerile cu caracter nevralgiform."},{"id":"B","text":"Resorbția radiculară la nivelul incisivului lateral și/sau a incisivilor centrali."},{"id":"C","text":"Închiderea completă a spațiului necesar pentru erupția caninului."},{"id":"D","text":"Modificările de poziție ale dinților vecini, precum rotațiile."},{"id":"E","text":"Procesele inflamatorii de tipul pericoronaritelor."}],"correct":["B"],"pages":[474],"source":"set-2"},{"id":"set2-FaI2zoix","fingerprint":"6397a34d44ff500b","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Referitor la resorbția radiculară cauzată de incluzia caninului superior, care dintre următoarele afirmații sunt adevărate?","options":[{"id":"A","text":"Afectează mult mai frecvent incisivii centrali în raport cu cei laterali."},{"id":"B","text":"Este frecvent evidențiată palatinal la nivelul incisivului lateral."},{"id":"C","text":"Este localizată cu precădere în porțiunea cervicală a rădăcinii."},{"id":"D","text":"Formele cele mai severe pot expune și afecta pulpa, fiind prezente de obicei la nivel apical."},{"id":"E","text":"Poate fi decelată cu ușurință în stadiu incipient pe imaginile radiologice convenționale."}],"correct":["B","D"],"pages":[474],"source":"set-2"},{"id":"set2-p5eEsTWC","fingerprint":"bc7ff9cfacdce42c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este considerat semnul clinic patognomonic pentru incluzia incisivului central superior cauzată de un obstacol, precum dinții supranumerari?","options":[{"id":"A","text":"Prezența unui dinte supranumerar erupt ce ocupă total spațiul incisivului central."},{"id":"B","text":"Disto-înclinația accentuată a incisivului lateral adiacent."},{"id":"C","text":"Absența incisivului central permanent de pe arcadă, asociată cu persistența predecesorului temporar fără mobilitate sau cu mobilitate redusă."},{"id":"D","text":"O deformare vestibulară dură, bine delimitată, în zona apicală a incisivului lateral."},{"id":"E","text":"Apariția unei diasteme semnificative între incisivul central erupt și incisivul lateral."}],"correct":["C"],"pages":[474],"source":"set-2"},{"id":"set2-i0kqyvA3","fingerprint":"6f6fbf41fb298c4e","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"În procesul de diagnosticare a incluziei dentare, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Anomalia este frecvent descoperită tardiv în cazul incluziei dinților succesionali datorită persistenței predecesorilor temporari."},{"id":"B","text":"Diagnosticul de certitudine se stabilește pe baza palpării unei deformări dure, incompresibile."},{"id":"C","text":"Există un tip de investigare radiologică specifică și suficientă pentru un diagnostic complet."},{"id":"D","text":"Examenul clinic este important pentru stabilirea unui diagnostic prezumtiv."},{"id":"E","text":"Examenul radiologic este indispensabil pentru a preciza relația dintelui inclus cu structurile anatomice învecinate."}],"correct":["A","D","E"],"pages":[474],"source":"set-2"},{"id":"set2-WOrFyUCa","fingerprint":"9432d9d5fc73df83","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce reprezintă semnul lui Quintero în contextul incluziei caninului superior?","options":[{"id":"A","text":"Prezența unei fistule cronice la nivelul gingiei atașate a incisivului lateral."},{"id":"B","text":"Mobilitatea incisivului lateral cauzată de presiunea exercitată de caninul inclus."},{"id":"C","text":"Resorbția radiculară severă localizată pe fața palatinală a incisivului lateral."},{"id":"D","text":"Bascularea coroanei incisivului lateral spre distal, cu apexul spre mezial."},{"id":"E","text":"Poziția vestibularizată a coroanei incisivului lateral superior și rotația sa mezio-vestibulară."}],"correct":["E"],"pages":[474],"source":"set-2"},{"id":"set2-F3LBdVjY","fingerprint":"c291dbbe55ccdd1c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele informații pot fi obținute prin intermediul unei radiografii retroalveolare (rio) în cazul unui dinte inclus?","options":[{"id":"A","text":"Gradul resorbției radiculare a dinților temporari."},{"id":"B","text":"Morfologia coronară și/sau radiculară a dintelui inclus."},{"id":"C","text":"Eventuale resorbții radiculare la nivelul dinților vecini."},{"id":"D","text":"Relația dintelui inclus cu formațiuni anatomice precum sinusul maxilar sau canalul mandibular."},{"id":"E","text":"Localizarea vestibulară sau orală a dintelui inclus."}],"correct":["A","B","C"],"pages":[475],"source":"set-2"},{"id":"set2-qMrSOrHn","fingerprint":"c9928d448f14cda1","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este principala limitare a radiografiei retroalveolare în evaluarea unui dinte inclus?","options":[{"id":"A","text":"Nu furnizează informații despre localizarea vestibulară sau orală a dintelui."},{"id":"B","text":"Varianta digitală nu permite mărirea imaginilor pentru evidențierea detaliilor."},{"id":"C","text":"Imaginea obținută este semnificativ distorsionată față de dimensiunea reală."},{"id":"D","text":"Nu permite vizualizarea morfologiei coronare și radiculare."},{"id":"E","text":"Nu poate evidenția existența dintelui inclus în profunzimea osului."}],"correct":["A"],"pages":[475],"source":"set-2"},{"id":"set2-v4faWAQQ","fingerprint":"d2e7a037afdb8172","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce informații pot fi obținute prin intermediul unei ortopantomograme în contextul incluziilor dentare?","options":[{"id":"A","text":"Direcția exactă a axului lung al dintelui în plan sagital și vertical."},{"id":"B","text":"O imagine tridimensională detaliată fără prelucrare computerizată."},{"id":"C","text":"Relația dintelui inclus cu formațiuni anatomice precum sinusul maxilar, fosele nazale sau canalul mandibular."},{"id":"D","text":"Prezența unor formațiuni sau leziuni asociate, precum chisturi foliculare sau odontoame."},{"id":"E","text":"Existența unor obstacole pe traiectul eruptiv al dintelui inclus."}],"correct":["C","D","E"],"pages":[475],"source":"set-2"},{"id":"set2-tqMSG7_Z","fingerprint":"fa262876fd69cd7d","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Conform metodei sectoarelor pentru evaluarea caninilor incluși pe ortopantomogramă, ce definește plasarea cuspidului caninului în sectorul 2?","options":[{"id":"A","text":"Cuspidul caninului inclus este plasat distal de primul premolar."},{"id":"B","text":"Cuspidul caninului inclus este plasat între linia interincisivă și incisivul central."},{"id":"C","text":"Cuspidul caninului inclus este plasat între axul incisivului central și axul incisivului lateral."},{"id":"D","text":"Cuspidul caninului inclus este plasat între axul incisivului lateral și primul premolar."},{"id":"E","text":"Cuspidul caninului inclus se suprapune peste axul incisivului central."}],"correct":["C"],"pages":[475],"source":"set-2"},{"id":"set2-9_wgFN6Q","fingerprint":"69537097cd18e1d2","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"În ce situație, evaluată pe o ortopantomogramă, prognosticul pentru un canin este de incluzie, conform metodei sectoarelor?","options":[{"id":"A","text":"Cuspidul caninului se află în sectorul 2, iar unghiul intern dintre axul caninului și linia interincisivă este mai mare de 25°."},{"id":"B","text":"Cuspidul caninului se află în oricare dintre cele trei sectoare, dacă unghiul intern este mai mare de 25°."},{"id":"C","text":"Crește riscul de resorbție radiculară a incisivului lateral cu 50%."},{"id":"D","text":"Cuspidul caninului se află în sectorul 1, iar unghiul intern dintre axul caninului și linia interincisivă este mai mare de 25°."},{"id":"E","text":"Cuspidul caninului se află în sectorul 3, iar unghiul intern este mai mic de 25°."}],"correct":["A","D"],"pages":[475],"source":"set-2"},{"id":"set2-9OhEP9Wo","fingerprint":"4f30cf5a417bfd6c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt limitările ortopantomogramei menționate în evaluarea dinților incluși?","options":[{"id":"A","text":"Furnizează o imagine de ansamblu doar pentru o singură arcadă alveolo-dentară."},{"id":"B","text":"Nu se poate evalua cu exactitate axul caninilor."},{"id":"C","text":"Nu oferă informații despre relația dintelui inclus cu sinusul maxilar."},{"id":"D","text":"Imposibilitatea de a mări zonele de interes în varianta sa digitalizată."},{"id":"E","text":"Suprapunerea și distorsionarea structurilor, în special în regiunea incisivilor."}],"correct":["B","E"],"pages":[475],"source":"set-2"},{"id":"set2-EvjeHTCW","fingerprint":"434cb7be51fe8b5f","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce tip de investigare radiologică este specificată ca fiind utilă pentru a oferi informații despre direcția axului lung al dintelui în plan sagital și vertical?","options":[{"id":"A","text":"Radiografia excentrică."},{"id":"B","text":"Ortopantomograma computerizată."},{"id":"C","text":"Radiografia retroalveolară izometrică și ortoradială (rio)."},{"id":"D","text":"Teleradiografia cranio-facială de profil."},{"id":"E","text":"Radiografia ocluzală."}],"correct":["D"],"pages":[475],"source":"set-2"},{"id":"set2-xntGFDkf","fingerprint":"214cd95a72c39ca3","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt informațiile specifice oferite de teleradiografia de profil în evaluarea unui dinte inclus?","options":[{"id":"A","text":"Posibilitatea de reconstrucție 3D a poziției dintelui."},{"id":"B","text":"Localizarea antero-posterioară și verticală a dintelui inclus."},{"id":"C","text":"Vizualizarea interrelațiilor complexe dintre structurile anatomice examinate, fără suprapuneri."},{"id":"D","text":"O imagine volumetrică de mare acuratețe a realității anatomice."},{"id":"E","text":"Direcția axului lung al dintelui în plan sagital și vertical."}],"correct":["B","E"],"pages":[476],"source":"set-2"},{"id":"set2-rHAJ4C5t","fingerprint":"cb0203245d5e5860","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele reprezintă avantaje ale utilizării tomografiei computerizate cu fascicul conic (CBCT) în diagnosticul dinților incluși?","options":[{"id":"A","text":"Doza de radiații la care este expus pacientul este scăzută."},{"id":"B","text":"Permite reconstrucția 3D și identificarea cu ușurință a poziției tridimensionale a dintelui."},{"id":"C","text":"Elimină suprapunerile de imagini, oferind o vizualizare de mare acuratețe."},{"id":"D","text":"Pot fi generate retroactiv diverse imagini din perspective diferite dintr-o singură achiziție."},{"id":"E","text":"Este utilizată în mod seriat pentru a aprecia evoluția dintelui în timpul tratamentului ortodontic."}],"correct":["A","B","C","D"],"pages":[476],"source":"set-2"},{"id":"set2-EbaY-gOh","fingerprint":"c47e955175a85545","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce elemente legate de un dinte inclus pot genera dificultăți în stabilirea atitudinii terapeutice?","options":[{"id":"A","text":"Diagnosticul de prezență a incluziei dentare."},{"id":"B","text":"Eventualele complicații asociate."},{"id":"C","text":"Profunzimea incluziei."},{"id":"D","text":"Orientarea și tendința evolutivă a dintelui."},{"id":"E","text":"Sediul exact al dintelui în grosimea osului alveolar."}],"correct":["B","C","D","E"],"pages":[476],"source":"set-2"},{"id":"set2-AuLVohcU","fingerprint":"07a3300087a4fa7c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"În ce situație este indicată cu precădere metoda radicală, extracționistă, de obținere a spațiului în tratamentul incluziei dentare?","options":[{"id":"A","text":"Părinții pacientului sunt reticenți față de extracția unui dinte sănătos."},{"id":"B","text":"Dintele inclus și-a reluat spontan evoluția în timpul tratamentului ortodontic."},{"id":"C","text":"Spațiul necesar este redus, dar poate fi obținut prin stimularea dezvoltării transversale a arcadei."},{"id":"D","text":"Spațiul necesar alinierii dinților este complet închis, iar procesul permutării dentare a fost încheiat."},{"id":"E","text":"Pacientul se află în dentiția mixtă și se dorește stimularea dezvoltării sagitale a arcadei."}],"correct":["D"],"pages":[476],"source":"set-2"},{"id":"set2-7jKNk82A","fingerprint":"a56a765abd712370","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care este abordarea chirurgicală corectă în funcție de localizarea unui dinte inclus?","options":[{"id":"A","text":"Pentru incluziile intraosoase, intervenția vizează eliberarea coroanei dintelui cu un sacrificiu osos cât mai redus."},{"id":"B","text":"Ancorarea dintelui inclus este o etapă absolut necesară în toate situațiile de incluzie dentară."},{"id":"C","text":"Îndepărtarea obstacolelor care au determinat incluzia se realizează într-o ședință separată, ulterioară intervenției chirurgicale."},{"id":"D","text":"Crearea unui tunel osos este procedura standard pentru dinții aflați în incluzie submucoasă."},{"id":"E","text":"Pentru dinții în incluzie submucoasă, este suficientă o decapușonare largă pentru a evita reacoperirea dintelui."}],"correct":["A","E"],"pages":[476],"source":"set-2"},{"id":"set2-3xVtZ10y","fingerprint":"3f36d8f5df78489c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care dintre următoarele afirmații referitoare la principiile tratamentului ortodontic al dinților incluși este adevărată?","options":[{"id":"A","text":"Intervenția chirurgicală pentru dinții incluși intraosos necesită un sacrificiu osos extins pentru a fi eficientă."},{"id":"B","text":"Extracția unui dinte sănătos în scop ortodontic este o metodă necontroversată."},{"id":"C","text":"Metodele conservatoare de obținere a spațiului nu sunt aplicabile în situațiile în care spațiul este complet închis."},{"id":"D","text":"Un dinte inclus nu poate erupe niciodată spontan, nici măcar după îndepărtarea obstacolelor."},{"id":"E","text":"Ancorarea dintelui este întotdeauna prima etapă a tratamentului, precedând obținerea spațiului."}],"correct":["C"],"pages":[476],"source":"set-2"},{"id":"set2-9g6_R_3i","fingerprint":"f02e7058640c0114","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este abordarea chirurgicală recomandată în cazul unui dinte în incluzie intraosoasă?","options":[{"id":"A","text":"Realizarea unui tunel osos cu un sacrificiu osos minim pentru a ghida erupția."},{"id":"B","text":"Ligaturarea peritisulară a dintelui pentru a facilita tracțiunea imediată."},{"id":"C","text":"O decapușonare largă pentru a preveni reacoperirea dintelui cu mucoasă."},{"id":"D","text":"Aplicarea de forțe ortodontice moderate pentru a stimula erupția fără intervenție chirurgicală."},{"id":"E","text":"Îndepărtarea obstacolelor și menținerea unui tunel de erupție, fără a se interveni asupra osului."}],"correct":["A"],"pages":[477],"source":"set-2"},{"id":"set2-zjUxlsWy","fingerprint":"1235cadd7916bf34","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care dintre următoarele condiții favorizează erupția spontană a unui dinte inclus după îndepărtarea chirurgicală a obstacolelor?","options":[{"id":"A","text":"Dintele se află într-o poziție aproape orizontală."},{"id":"B","text":"Dintele se află în incluzie înaltă."},{"id":"C","text":"Dintele inclus are o morfologie atipică."},{"id":"D","text":"Dintele este ancorat intratisular."},{"id":"E","text":"Cauza incluziei a fost persistența predecesorului temporar."}],"correct":["E"],"pages":[477],"source":"set-2"},{"id":"set2-vuzhTAt4","fingerprint":"3636cdb97328fc61","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt afirmațiile corecte cu privire la tehnica de ancorare peritisulară a unui dinte inclus?","options":[{"id":"A","text":"Implică realizarea unui tunel transcoronar la jumătatea distanței dintre marginea incizală și camera pulpară."},{"id":"B","text":"Componentele orizontale ale redresării dintelui se realizează în condiții optime."},{"id":"C","text":"Este o tehnică ce respectă integritatea morfologică a dintelui."},{"id":"D","text":"Necesită un sacrificiu considerabil de substanță osoasă."},{"id":"E","text":"Presupune cimentarea unui cârlig într-o cavitate retentivă realizată pe fața orală a dintelui."}],"correct":["C","D"],"pages":[477],"source":"set-2"},{"id":"set2-wX7j5ED5","fingerprint":"f99cfd8e2743d777","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este principala critică adusă tehnicilor de ancorare intratisulară și transtisulară, care a dus la utilizarea lor redusă sau la abandonarea lor?","options":[{"id":"A","text":"Sacrificiul mare de substanță osoasă necesar pentru aplicarea ligaturii."},{"id":"B","text":"Dificultatea de a asigura o hemostază corespunzătoare în timpul intervenției."},{"id":"C","text":"Riscul frecvent de descimentare a cârligului, necesitând o nouă intervenție."},{"id":"D","text":"Realizarea dificilă a componentelor orizontale ale deplasării dentare."},{"id":"E","text":"Sacrificiul de substanță dentară, care vulnerabilizează dintele."}],"correct":["E"],"pages":[477],"source":"set-2"},{"id":"set2-s8F5saCA","fingerprint":"51fdc18a2c4ec690","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este cea mai utilizată modalitate de ancorare a dinților incluși în practica ortodontică actuală și de ce este preferată?","options":[{"id":"A","text":"Lipsa ancorării, deoarece dinții pot evolua spontan în majoritatea situațiilor."},{"id":"B","text":"Ancorarea intratisulară, pentru că permite aplicarea tracțiunii la extremitatea dintelui."},{"id":"C","text":"Ancorarea prin colarea unor accesorii, deoarece protejează substratul dentar și osos."},{"id":"D","text":"Ancorarea peritisulară, deoarece asigură posibilități foarte bune pentru tracțiune."},{"id":"E","text":"Ancorarea transtisulară, deoarece ancorarea este foarte sigură."}],"correct":["C"],"pages":[477],"source":"set-2"},{"id":"set2-CxUP4Ubf","fingerprint":"7dc97cd988065c81","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este o consecință a utilizării unor forțe excesive în timpul etapei de tracționare a unui dinte inclus?","options":[{"id":"A","text":"Resorbția radiculară a dinților vecini."},{"id":"B","text":"Fracturarea marginii incizale a dintelui tracționat."},{"id":"C","text":"Apariția unui țesut acelular hialin care împiedică erupția."},{"id":"D","text":"Accelerarea erupției dintelui și scurtarea duratei de tratament."},{"id":"E","text":"Descimentarea frecventă a accesoriilor colate."}],"correct":["C"],"pages":[477],"source":"set-2"},{"id":"set2-hbYAJnX1","fingerprint":"7cc56aa458094db7","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații descriu corect importanța morfo-funcțională a caninului?","options":[{"id":"A","text":"Are o rezistență scăzută la carie, fiind frecvent afectat."},{"id":"B","text":"Are un rol secundar în ghidajul mișcărilor de lateralitate, acesta fiind preluat de dinții posteriori."},{"id":"C","text":"Este un dinte cu o implantare mai slabă decât a celorlalți dinți frontali."},{"id":"D","text":"Este considerat un stâlp al ocluziei datorită poziției sale strategice în zona de curbură a arcadei."},{"id":"E","text":"Lipsa protecției asigurate de canin crește susceptibilitatea la anomalii de clasa a III-a Angle."}],"correct":["D","E"],"pages":[477],"source":"set-2"},{"id":"set2-mmgkEFki","fingerprint":"17411fb460dcafe7","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Ce impact negativ poate avea absența ghidajului funcțional asigurat de către canin?","options":[{"id":"A","text":"Susceptibilitate crescută de cinci ori la anomaliile de clasa a II-a Angle."},{"id":"B","text":"Apariția unui țesut acelular hialin care blochează mișcările dentare."},{"id":"C","text":"O conexiune deficitară între incisivi și premolari, ducând la fracturi dentare."},{"id":"D","text":"Impact negativ asupra articulației temporo-mandibulare și resorbție radiculară la dinții vecini."},{"id":"E","text":"Creșterea riscului de lezare a pulpei dentare la pacienții tineri."}],"correct":["D"],"pages":[477],"source":"set-2"},{"id":"set2-nsevkQfn","fingerprint":"77d5a95d41147be8","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Referitor la procesul de tracționare a unui dinte pe arcadă, care dintre următoarele afirmații sunt corecte?","options":[{"id":"A","text":"Tracționarea trebuie începută imediat post-operator pentru a obține cele mai bune rezultate."},{"id":"B","text":"Procesul se inițiază la 8-15 zile de la intervenția chirurgicală."},{"id":"C","text":"Utilizarea unor forțe care nu sunt moderate duce la formarea unui țesut acelular hialin."},{"id":"D","text":"Este necesară aplicarea unor forțe moderate pentru a stimula erupția."},{"id":"E","text":"Țesutul acelular hialin format în urma aplicării forțelor incorecte facilitează erupția."}],"correct":["B","C","D"],"pages":[478],"source":"set-2"},{"id":"set2--TuYCeRu","fingerprint":"404bb19ce63a937e","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele caracteristici subliniază importanța morfo-funcțională a dintelui canin?","options":[{"id":"A","text":"Este considerat un stâlp al ocluziei datorită poziției sale strategice în zona de curbură a arcadei."},{"id":"B","text":"Rolul său funcțional principal este similar cu cel al molarilor în masticație."},{"id":"C","text":"Este dintele cel mai puțin implicat în patologia ortodontică de incluzie."},{"id":"D","text":"Are o rezistență deosebită la carie și o valoare parodontală și protetică importantă."},{"id":"E","text":"Este considerat dintele cel mai robust și mai lung, cu cea mai bună implantare dintre dinții frontali."}],"correct":["A","D","E"],"pages":[478],"source":"set-2"},{"id":"set2-kNfy8HFh","fingerprint":"e4e3ceab4b0814c2","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt consecințele negative asociate cu absența ghidajului canin?","options":[{"id":"A","text":"O susceptibilitate de cinci ori mai mare la anomaliile de clasa a III-a Angle."},{"id":"B","text":"O creștere a rezistenței la carie a dinților posteriori."},{"id":"C","text":"Apariția frecventă a resorbției radiculare la nivelul dinților vecini."},{"id":"D","text":"O susceptibilitate crescută la anomalii de clasa a I-a Angle."},{"id":"E","text":"Un impact negativ asupra articulației temporo-mandibulare."}],"correct":["A","C","E"],"pages":[478],"source":"set-2"},{"id":"set2-gGweLyel","fingerprint":"d21d450d3c218640","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"În ce situații excepționale poate fi luată în considerare extracția unui canin inclus?","options":[{"id":"A","text":"Dacă dintele prezintă modificări morfologice majore care fac imposibilă alinierea sa pe arcadă."},{"id":"B","text":"Atunci când există o lipsă minoră de spațiu pe arcadă."},{"id":"C","text":"În toate cazurile de incluzie a caninului superior pentru a scurta durata tratamentului ortodontic."},{"id":"D","text":"Dacă pacientul solicită extracția din considerente estetice."},{"id":"E","text":"Când caninul este în poziție orizontală, iar ceilalți dinți sunt aliniați și în relații interarcadice echilibrate."}],"correct":["A","E"],"pages":[478],"source":"set-2"},{"id":"set2-JVdq7TZf","fingerprint":"9fb1bf64b4ad3bb6","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt încadrările taxonomice ale incluziei dentare în funcție de diferitele școli și sisteme de clasificare ortodontică?","options":[{"id":"A","text":"Clasificarea românească o încadrează în grupa anomaliilor dentare izolate, cu referire specială la anomaliile dentare de erupție."},{"id":"B","text":"Clasificarea germană plasează incluzia dentară în grupa anomaliilor dentare."},{"id":"C","text":"Clasificarea americană încadrează incluzia dentară în clasa I."},{"id":"D","text":"Clasificarea germană introduce această anomalie în grupa dizarmoniilor sistemului dentar."},{"id":"E","text":"Clasificarea franceză o regăsește în grupa anomaliilor dentare izolate."}],"correct":["A","B","C"],"pages":[468],"source":"set-2"},{"id":"set2--qdnbLwx","fingerprint":"dc3ebf7f753e4b5c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt particularitățile epidemiologice și de frecvență care caracterizează incluzia dentară?","options":[{"id":"A","text":"Ordinea frecvenței pe tipuri de dentiție este reprezentată de dinții permanenți, urmați de dinții supranumerari și de dinții temporari."},{"id":"B","text":"Se manifestă mult mai frecvent la genul masculin comparativ cu cel feminin."},{"id":"C","text":"Incluzia dinților temporari este o situație clinică frecventă, afectând cu predilecție incisivii superiori."},{"id":"D","text":"Premolarul 2 inferior este mai frecvent interesat de incluzie comparativ cu incisivul central superior."},{"id":"E","text":"În dentiția permanentă, ordinea descrescătoare a frecvenței este: molarul de minte, caninul, premolarul 2 și incisivul central superior."}],"correct":["A","D","E"],"pages":[468],"source":"set-2"},{"id":"set2-xmc_xf7f","fingerprint":"55f9d91a2685d372","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este afirmația ce descrie riguros caracteristicile clinice și topografice ale incluziei de canin?","options":[{"id":"A","text":"Din perspectiva cazuisticii ortodontice, incluziile de canin reprezintă un procent situat sub 20% din totalul incluziilor dentare."},{"id":"B","text":"Frecvența incluziei caninului inferior este semnificativ mai mare decât cea a caninului superior."},{"id":"C","text":"Caninul se individualizează prin cel mai profund loc de formare și cea mai lungă perioadă de dezvoltare dintre toți dinții."},{"id":"D","text":"Localizarea caninului inclus la arcada superioară este predominant vestibulară."},{"id":"E","text":"Incluzia de canin se manifestă bilateral în marea majoritate a cazurilor clinice."}],"correct":["C"],"pages":[469],"source":"set-2"},{"id":"set2-1nrfU-ts","fingerprint":"2f57675dd8d85efb","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt elementele fiziopatologice și topografice asociate cu fenomenul de transmigrație dentară și cu etiopatogenia incluziei de canin?","options":[{"id":"A","text":"Caninul prezintă cel mai sinuos traiect de la locul de formare până la atingerea planului de ocluzie."},{"id":"B","text":"Transmigrația dentară descrie anomalia atipică în care un canin neerupt migrează intraosos și traversează linia mediană."},{"id":"C","text":"Caninul superior are cea mai mare variabilitate a perioadei de erupție dintre toți dinții de pe arcade, fără nicio excepție."},{"id":"D","text":"Migrarea intraosoasă cu depășirea liniei mediane se produce cel mai adesea pe un traseu palatinal sau lingual."},{"id":"E","text":"Caninul permanent, în special cel inferior, este cel mai frecvent implicat în fenomenul de transmigrație dentară."}],"correct":["A","B","E"],"pages":[469],"source":"set-2"},{"id":"set2-is3J7pOF","fingerprint":"7a0eada0873e3ef0","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce trăsături definesc anomalia de erupție denumită incluzie dentară?","options":[{"id":"A","text":"Presupune rămânerea unui dinte complet format în interiorul osului maxilar sau submucos, mult peste vârsta sa normală de erupție."},{"id":"B","text":"Prezintă o prevalență crescută în rândul populației de gen feminin."},{"id":"C","text":"Erupția caninului superior se produce exclusiv în intervalul de vârstă 14-16 ani."},{"id":"D","text":"Incluzia dinților temporari se obiectivează în mod predominant la nivelul molarilor superiori."},{"id":"E","text":"Incluzia palatinală a caninului este de două ori mai frecventă comparativ cu alte localizări."}],"correct":["A","B","E"],"pages":[468],"source":"set-2"},{"id":"set2-qLRQcKg6","fingerprint":"97f7180cbfc16603","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații referitoare la factorii locali implicați în deficitul de spațiu și etiologia incluziei dentare sunt adevărate?","options":[{"id":"A","text":"Macrodonția absolută se definește printr-o sumă incisivă mai mare de 35 mm sau printr-o lățime mezio-distală a incisivilor centrali de cel puțin 1 cm fiecare."},{"id":"B","text":"În macrodonția relativă, suma incisivă depășește valoarea de 35 mm, deși dinții par normali în raport cu diametrul bizigomatic osos al pacientului."},{"id":"C","text":"Dezvoltarea insuficientă a maxilarelor afectează în principal dinții care erup primii pe arcadă, din cauza lipsei suportului osos la nivel anterior."},{"id":"D","text":"Meziopozițiile generalizate oferă un substrat explicativ atât pentru incluziile dentare unilaterale, cât și pentru cele bilaterale."},{"id":"E","text":"Macrodonția și insuficienta dezvoltare a oaselor maxilare constituie suport explicativ cu predilecție pentru incluziile dentare bilaterale."}],"correct":["A","D","E"],"pages":[470],"source":"set-2"},{"id":"set2-nr857rtq","fingerprint":"8ed181c327e426d5","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care dintre următoarele particularități etiopatogenice diferențiază incluzia caninului permanent cu localizare vestibulară de cea orală?","options":[{"id":"A","text":"Excesul masiv de spațiu pe arcada superioară modifică traiectul eruptiv orientat spre vestibular, forțând caninul să se poziționeze în incluzie orală."},{"id":"B","text":"Deficitul de spațiu determină predominant incluzia de canin cu localizare palatinală, deoarece traiectul evolutiv normal al dintelui este orientat spre oral."},{"id":"C","text":"Incluzia cu localizare orală a caninului apare frecvent pe fondul macrodonției absolute și se asociază cu o creștere accentuată în volum a dinților succesori."},{"id":"D","text":"Incluzia de canin cu localizare vestibulară se instalează frecvent pe fondul unui spațiu suficient pentru erupție, având asocieri strânse cu anodonția."},{"id":"E","text":"Majoritatea cazurilor de incluzie a caninului în poziție palatinală beneficiază de spațiu suficient pentru erupție, anomalia fiind asociată cu un determinism ereditar recunoscut."}],"correct":["E"],"pages":[470],"source":"set-2"},{"id":"set2-8kB38Ljw","fingerprint":"ce422a13bbeee86b","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Cum influențează fenomenul de reducere filogenetică a aparatului dento-maxilar procesul de aliniere și probabilitatea apariției incluziilor dentare?","options":[{"id":"A","text":"Evoluția filogenetică a aparatului dento-maxilar determină în mod sistematic prezența unor spații excedentare pe arcada superioară."},{"id":"B","text":"Ritmul de reducere filogenetică a maxilarelor este mai rapid comparativ cu cel al reducerii numărului și/sau volumului dentar."},{"id":"C","text":"Condițiile care favorizează incluzia dentară, apărute ca urmare a involuției filogenetice, se adresează în mod special ultimilor dinți care urmează să erupă."},{"id":"D","text":"Procesul de reducție implică o descreștere progresivă a oaselor maxilare cu un ritm mult mai lent decât cel de reducere al volumului dentar."},{"id":"E","text":"Diferența de ritm între reducerea bazei osoase și reducerea dentară duce la o restrângere considerabilă a spațiului necesar erupției."}],"correct":["B","C","E"],"pages":[470],"source":"set-2"},{"id":"set2-gIzM2hXL","fingerprint":"d8283d0184c3f133","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele elemente reprezintă obstacole locale cu potențial etiologic recunoscut pentru dezvoltarea incluziei dentare?","options":[{"id":"A","text":"Procesele inflamatorii cronice de lungă durată de la nivelul dinților temporari, care conduc la osteoscleroză alveolară."},{"id":"B","text":"Fibromucoasa densă și dură constituită în urma unor extracții dentare precoce sau pe fondul hiperplaziilor gingivale."},{"id":"C","text":"Prezența dinților supranumerari induce cu precădere incluzii în regiunile laterale, având o afinitate exclusivă pentru zonele retromolare."},{"id":"D","text":"Osteoscleroza procesului alveolar, apărută ca urmare a traumatismelor suferite sau în cadrul osteitei deformante."},{"id":"E","text":"Persistența caninului temporar peste termenul de permutare din cauza lipsei resorbției radiculare nu poate fi considerată sub nicio formă un factor cauzal al incluziei, fiind strict o consecință a unui traiect deviat."}],"correct":["A","B","D"],"pages":[471],"source":"set-2"},{"id":"set2--yk8cMFT","fingerprint":"1c7515e7240f1754","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele caracteristici particulare ale mugurelui sau dintelui intraosos sunt implicate în mod direct în apariția incluziei dentare?","options":[{"id":"A","text":"Poziționarea anormală în sens transversal, manifestată prin așezarea dintelui de-a curmezișul arcadei alveolare."},{"id":"B","text":"Conformația anatomică particulară, caracterizată prin prezența unei coroane foarte globuloase sau a unei curburi radiculare accentuate."},{"id":"C","text":"Modificarea poziției intraosoase a dintelui în sens sagital, generând mezioînclinații accentuate care pot atinge orizontalitatea completă."},{"id":"D","text":"Mugurele caninului superior se formează într-o poziție foarte înaltă, având de străbătut un traseu eruptiv considerabil mai scurt comparativ cu incisivii centrali."},{"id":"E","text":"Pierderea exclusiv definitivă a potențialului eruptiv al dintelui, neexistând posibilitatea ca un dinte să își reia evoluția la vârste înaintate."}],"correct":["A","B","C"],"pages":[471],"source":"set-2"},{"id":"set2-n24L_9r8","fingerprint":"fe76b5296e960a09","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele patologii și condiții sunt considerate factori etiologici generali în apariția incluziei dentare?","options":[{"id":"A","text":"Sindroamele genetice precum sindromul Down și sindromul Turner"},{"id":"B","text":"Disfuncțiile endocrine precum nanismul hipofizar"},{"id":"C","text":"Hipertiroidismul sever necontrolat"},{"id":"D","text":"Disostoza cleidocraniană mediată prin hiperfuncția osteoblastelor"},{"id":"E","text":"Despicăturile labio-maxilo-palatine"}],"correct":["A","B","E"],"pages":[471],"source":"set-2"},{"id":"set2-4eitKz7r","fingerprint":"6ff35515978b5b0a","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este mecanismul patogenic incriminat în apariția incluziei dentare la pacienții diagnosticați cu disostoză cleidocraniană?","options":[{"id":"A","text":"Acțiunea directă a radiațiilor X și a factorilor de poluare asupra sacului folicular"},{"id":"B","text":"Deficitul sever de vitamina C în perioada de formare a foliculului dentar"},{"id":"C","text":"Anomaliile de formă și volum ale incisivului lateral"},{"id":"D","text":"Proliferarea excesivă a osteoblastelor"},{"id":"E","text":"Disfuncția osteoclastelor"}],"correct":["E"],"pages":[471],"source":"set-2"},{"id":"set2-3sbV7GNs","fingerprint":"7ea4e560849e1b1d","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce particularități caracterizează influența factorului ereditar în etiopatogenia incluziei dentare?","options":[{"id":"A","text":"Demonstrează faptul că factorii loco-regionali nu au nicio influență asupra șanselor de erupție a dintelui."},{"id":"B","text":"Este adesea însoțit de anodonția incisivului lateral sau a altor dinți."},{"id":"C","text":"Este discutat cu predilecție în cazul incluziei de canin, în special în forma sa palatinală."},{"id":"D","text":"Se asociază frecvent cu modificări de formă și volum ale incisivului lateral."},{"id":"E","text":"Se manifestă independent de orice alte anomalii dentare determinate genetic."}],"correct":["B","C","D"],"pages":[471],"source":"set-2"},{"id":"set2-t99SuWui","fingerprint":"39d8e14586e686f4","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afecțiuni sunt recunoscute ca factori etiologici generali ai incluziei dentare?","options":[{"id":"A","text":"Gigantismul hipofizar"},{"id":"B","text":"Sindromul Down"},{"id":"C","text":"Boala Paget"},{"id":"D","text":"Hipervitaminoza D"},{"id":"E","text":"Rahitismul"}],"correct":["B","C","E"],"pages":[471],"source":"set-2"},{"id":"set2-VwHzoVAm","fingerprint":"24f298f038ac5148","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt afirmațiile referitoare la clasificarea incluziei dentare în funcție de gradul de severitate, apreciat pe ortopantomogramă?","options":[{"id":"A","text":"Incluzia dentară ușoară presupune o distanță limitată inferior, cuprinsă între 8 și 12 mm până la planul de ocluzie."},{"id":"B","text":"Incluzia dentară ușoară sau joasă presupune o distanță mai mică de 12 mm până la planul de ocluzie."},{"id":"C","text":"Incluzia dentară severă se caracterizează printr-o distanță cuprinsă strict între 15 și 20 mm până la planul de ocluzie."},{"id":"D","text":"Incluzia dentară severă sau înaltă presupune o distanță mai mare de 15 mm până la planul de ocluzie."},{"id":"E","text":"Incluzia dentară medie presupune o distanță cuprinsă între 12 și 15 mm până la planul de ocluzie."}],"correct":["B","D","E"],"pages":[472],"source":"set-2"},{"id":"set2-2zq8E3H1","fingerprint":"13d79ce49e89b275","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care este definiția incluziei de canin gradul 2, atunci când se utilizează drept reper înălțimea verticală a coroanei caninului inclus în raport cu incisivul adiacent?","options":[{"id":"A","text":"Coroana caninului inclus se află sub nivelul joncțiunii smalț-cement a incisivului lateral."},{"id":"B","text":"Coroana caninului inclus se află deasupra nivelului joncțiunii smalț-cement, dar se suprapune peste mai puțin de jumătate din lățimea rădăcinii incisivului lateral."},{"id":"C","text":"Coroana caninului inclus se află deasupra nivelului joncțiunii smalț-cement, la mai mult de jumătate din înălțimea rădăcinii incisivului lateral, neajungând la apex."},{"id":"D","text":"Coroana caninului inclus se află deasupra apexului incisivului lateral."},{"id":"E","text":"Coroana caninului inclus se află deasupra nivelului joncțiunii smalț-cement, dar la mai puțin de jumătate din înălțimea rădăcinii incisivului lateral."}],"correct":["E"],"pages":[472],"source":"set-2"},{"id":"set2-P_PdT_WL","fingerprint":"42eaac67e28e9c68","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele tipuri de incluzii dentare aparțin clasificării realizate în funcție de direcția axului dintelui inclus?","options":[{"id":"A","text":"Incluzia dentară ectopică, caracterizată printr-un ax orizontal la distanță de locul normal de evoluție."},{"id":"B","text":"Incluzia dentară cu anchiloză dentară, în care dintele prezintă o orientare oblică spre mezial."},{"id":"C","text":"Incluzia dentară vestibulo-orală, în care dintele este orientat cu coroana spre vestibular și cu rădăcina spre oral, denumită și poziția „a cheval”."},{"id":"D","text":"Incluzia dentară în retroversie, în care dintele are coroana orientată invers sensului de erupție."},{"id":"E","text":"Incluzia dentară orizontală, în care coroana dintelui inclus este situată între rădăcinile dinților erupți, iar rădăcina acestuia este orientată spre distal."}],"correct":["C","D","E"],"pages":[473],"source":"set-2"},{"id":"set2-YZzJINtJ","fingerprint":"c249fa391a2616b9","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt afirmațiile valabile cu privire la criteriile de clasificare după locul de dezvoltare al dinților incluși?","options":[{"id":"A","text":"Incluzia dentară normală presupune localizarea dinților incluși la locul în care, în mod normal, evoluează germenul dentar."},{"id":"B","text":"Heterotopia dentară reprezintă situația unui dinte ce se formează în altă parte decât locul său normal, cum ar fi marginea bazilară, condilul mandibular sau fosele nazale."},{"id":"C","text":"Incluzia dentară ectopică presupune prezența dintelui la distanță de locul în care evoluează germenul dentar, dar exclusiv în afara limitelor procesului alveolar."},{"id":"D","text":"Incluzia dentară ectopică se caracterizează prin găsirea dinților la distanță de locul normal de evoluție a germenului dentar, menținându-se însă în limitele procesului alveolar."},{"id":"E","text":"Heterotopia dentară descrie situația în care un dinte se dezvoltă în limitele procesului alveolar, prezentând o deviere a axului de erupție."}],"correct":["A","B","D"],"pages":[473],"source":"set-2"},{"id":"set2-KJpDcxPI","fingerprint":"cbbb367a6bcd9376","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele afirmații descriu caracteristici specifice gradului 3 din sistemele de clasificare ale incluziei de canin superior?","options":[{"id":"A","text":"Coroana caninului inclus se află deasupra nivelului joncțiunii smalț-cement, la mai mult de jumătate din înălțimea rădăcinii incisivului lateral, neajungând însă la apex."},{"id":"B","text":"Apexul caninului inclus este situat deasupra regiunii celui de-al doilea premolar."},{"id":"C","text":"Unghiul pe care îl face axul caninului cu linia mediană este cuprins între 16 și 30°."},{"id":"D","text":"Caninul inclus se suprapune complet peste lățimea rădăcinii incisivului lateral adiacent."},{"id":"E","text":"Unghiul pe care îl face axul caninului cu linia mediană este mai mare de 30°."}],"correct":["A","B","E"],"pages":[472],"source":"set-2"},{"id":"set2-Y4KDEBU6","fingerprint":"d6e8bdd57b4a8b1b","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele manifestări clinice intraorale pot sugera prezența unui dinte inclus?","options":[{"id":"A","text":"Dureri cu caracter nevralgiform, fără o cauză precizată."},{"id":"B","text":"Mobilitatea dinților vecini cauzată de hipercimentoza radiculară."},{"id":"C","text":"Existența unui dinte supranumerar erupt ce ocupă parțial sau chiar total spațiul dintelui din seria normală."},{"id":"D","text":"Persistența pe arcadă a dintelui temporar, în anumite situații clinice, cu o bună implantare."},{"id":"E","text":"Prezența unei deformări vestibulare sau orale de consistență moale, compresibilă."}],"correct":["A","C","D"],"pages":[474],"source":"set-2"},{"id":"set2-4P_ZfpQX","fingerprint":"194113a0d90c493b","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt caracteristicile și complicațiile clinice asociate incluziei caninului superior?","options":[{"id":"A","text":"Resorbția radiculară la nivelul incisivului lateral este evidențiată majoritar palatinal și localizată în porțiunea cervicală a rădăcinii."},{"id":"B","text":"Incisivul lateral prezintă frecvent o disto-înclinație accentuată cauzată de caninul inclus în poziție oblic mezială."},{"id":"C","text":"Rotația disto-vestibulară a coroanei incisivului lateral superior reprezintă semnul lui Quintero."},{"id":"D","text":"Complicația cea mai frecventă este resorbția radiculară, afectând mult mai des incisivul central în raport cu cel lateral."},{"id":"E","text":"Bascularea incisivului lateral se realizează cu vârful rădăcinii orientat spre mezial și coroana spre distal."}],"correct":["B","E"],"pages":[474],"source":"set-2"},{"id":"set2-0eOPss_q","fingerprint":"99e14a2f13fd0c6c","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt afirmațiile adevărate privind evaluarea poziției caninilor incluși prin metoda sectoarelor și prognosticul asociat?","options":[{"id":"A","text":"Sectorul 1 este definit de plasarea cuspidului caninului inclus între axul incisivului central și axul incisivului lateral."},{"id":"B","text":"Plasarea cuspidului caninului inclus în sectoarele 1 sau 2, asociată cu un unghi intern față de linia interincisivă mai mare de 25°, indică un prognostic de incluzie."},{"id":"C","text":"Încadrarea în sectoarele 1 sau 2 și un unghi mai mare de 25° determină scăderea riscului de resorbție radiculară a incisivului lateral cu 50%."},{"id":"D","text":"Sectorul 3 corespunde plasării cuspidului caninului inclus între axul incisivului lateral și primul premolar."},{"id":"E","text":"Sectorul 2 este definit de plasarea cuspidului caninului inclus între linia interincisivă și incisivul central."}],"correct":["B","D"],"pages":[475],"source":"set-2"},{"id":"set2-H_LOfN9-","fingerprint":"e0d24be3397ac5ce","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care dintre următoarele aspecte descriu caracteristicile incluziei incisivului central superior și investigațiile imagistice utilizate în incluziile dentare?","options":[{"id":"A","text":"Semnul clinic patognomonic al incluziei incisivilor centrali cauzată de dinți supranumerari este persistența predecesorilor temporari cu mobilitate accentuată."},{"id":"B","text":"Radiografia retroalveolară oferă informații exacte privind localizarea vestibulară sau orală a dintelui inclus."},{"id":"C","text":"Tomografia computerizată cu fascicul conic (CBCT) elimină suprapunerile structurale și permite identificarea precisă a poziției tridimensionale a dintelui inclus."},{"id":"D","text":"În peste 90% din cazurile de incluzie a incisivului central superior, cauza singulară este reprezentată de prezența dinților supranumerari incluși."},{"id":"E","text":"Pentru descoperirea precoce a resorbției radiculare pe fețele palatinale sau vestibulare se preferă exclusiv radiografia retroalveolară digitală în detrimentul tomografiei computerizate."}],"correct":["C","D"],"pages":[474],"source":"set-2"},{"id":"set2-gM_Slpsc","fingerprint":"65d31276001e6e56","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce informații oferă ortopantomograma și teleradiografia cranio-facială în investigarea dinților incluși?","options":[{"id":"A","text":"Teleradiografia cranio-facială de profil evaluează direcția axului lung al dintelui exclusiv în plan orizontal."},{"id":"B","text":"Teleradiografiile seriate realizate în cursul tratamentului ortodontic permit aprecierea evoluției dintelui inclus."},{"id":"C","text":"Ortopantomograma evidențiază relația dintelui inclus cu formațiuni anatomice învecinate, cum ar fi sinusul maxilar, fosele nazale și canalul mandibular."},{"id":"D","text":"Ortopantomograma permite determinarea cu exactitate absolută a axului caninilor incluși, fără distorsiuni de proiecție."},{"id":"E","text":"O limită majoră a ortopantomogramei este distorsionarea și suprapunerea structurilor exclusiv în regiunea molarilor de minte."}],"correct":["B","C"],"pages":[475],"source":"set-2"},{"id":"set2-3z8h6HdJ","fingerprint":"2e7c1f0432b69fdc","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt situațiile în care se poate lua în discuție extracția unui canin inclus?","options":[{"id":"A","text":"Când caninul prezintă o angulație corono-radiculară ce face imposibilă alinierea sa."},{"id":"B","text":"Când relațiile interarcadice sunt echilibrate, toți dinții sunt aliniați, dar caninul are o poziție orizontală."},{"id":"C","text":"Când lipsa spațiului pe arcadă impune folosirea unei metode extracționiste în dentiția mixtă."},{"id":"D","text":"Când arcada dentară prezintă diasteme și treme la nivelul incisivilor superiori."},{"id":"E","text":"Când caninul prezintă modificări morfologice majore care nu permit aducerea sa pe arcadă."}],"correct":["A","B","E"],"pages":[478],"source":"set-2"},{"id":"set2-EsZwP4J_","fingerprint":"5ca237ee773f25e5","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"Care sunt caracteristicile ancorării transtisulare utilizate în descoperirea chirurgicală și managementul incluziei dentare?","options":[{"id":"A","text":"Presupune ligaturarea dintelui în jurul coletului său."},{"id":"B","text":"Impune realizarea unui tunel transcoronar situat la jumătatea distanței dintre marginea incizală și tavanul camerei pulpare."},{"id":"C","text":"Necesită realizarea unei cavități retentive pe fața orală pentru cimentarea unui cârlig."},{"id":"D","text":"Oferă avantajul lipsei sacrificiului de substanță dentară și o estetică favorabilă."},{"id":"E","text":"Se bazează pe colarea unor accesorii precum bracketuri sau butoane."}],"correct":["B"],"pages":[477],"source":"set-2"},{"id":"set2-2bwOgU3a","fingerprint":"88ba44dc0853a134","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Ce fenomene și principii caracterizează etapa de tracționare și aliniere a unui dinte inclus pe arcadă?","options":[{"id":"A","text":"Se folosesc forțe moderate pentru a stimula erupția dintelui."},{"id":"B","text":"Tracțiunea utilizează forțe puternice și continue pentru o erupție accelerată."},{"id":"C","text":"Tracționarea începe la 8-15 zile de la intervenția chirurgicală."},{"id":"D","text":"Această etapă trebuie inițiată obligatoriu la toți dinții incluși, indiferent de profunzimea incluziei."},{"id":"E","text":"Aplicarea unor forțe necorespunzătoare poate determina apariția unui țesut acelular hialin care împiedică erupția."}],"correct":["A","C","E"],"pages":[477],"source":"set-2"},{"id":"set2-1M1o3EUG","fingerprint":"d884ad6b5ea69fe8","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CS","text":"În ce condiții sunt indicate extracțiile în dentiția permanentă ca metodă radicală de obținere a spațiului pentru un dinte inclus?","options":[{"id":"A","text":"Doar atunci când ancorarea peritisulară a eșuat din cauza hemostazei deficitare."},{"id":"B","text":"În toate cazurile în care spațiul necesar alinierii dinților este complet închis, iar procesul permutării dentare a fost încheiat."},{"id":"C","text":"Când dinții situați în incluzie submucoasă nu pot fi decapușonați."},{"id":"D","text":"Când spațiul necesar alinierii este ușor redus, iar procesul permutării dentare este în plină desfășurare."},{"id":"E","text":"Atunci când se dorește stimularea dezvoltării transversale a arcadei fără aparate ortodontice."}],"correct":["B"],"pages":[476],"source":"set-2"},{"id":"set2-i8AWFPdp","fingerprint":"307242f89a58a056","chapterId":"set-2","subchapterId":"set2-6.1.3","type":"CM","text":"Care sunt consecințele și caracteristicile asociate cu lipsa funcțională a caninului și cu rolul său pe arcadă?","options":[{"id":"A","text":"Caninul este considerat un stâlp al ocluziei exclusiv datorită poziției sale în zona incisivilor centrali."},{"id":"B","text":"Pacienții fără protecția caninului sunt de cinci ori mai susceptibili la anomalii de clasa a III-a Angle."},{"id":"C","text":"La nivelul dinților vecini se observă frecvent resorbție radiculară în absența ghidajului asigurat de canin."},{"id":"D","text":"Absența protecției canine crește de cinci ori susceptibilitatea la anomalii de clasa a II-a Angle."},{"id":"E","text":"Lipsa ghidajului canin are un impact negativ asupra articulației temporo-mandibulare."}],"correct":["B","C","E"],"pages":[477],"source":"set-2"}];
